// Separate demonstration ledger; existing client receipts are not automatically classified.
export const accounts={cash:['Cash / bank','asset'],receivable:['Accounts receivable','asset'],equipment:['Equipment','asset'],payable:['Accounts payable','liability'],clientfunds:['Client funds liability','liability'],capital:['Owner capital','equity'],revenue:['Service revenue','income'],expense:['Other operating expense','expense'],salary:['Salaries','expense'],rent:['Rent','expense'],software:['Software','expense'],advertising:['Advertising','expense']};
const customAccountsKey='crm-demo-custom-accounts-v1';
function customAccounts(){try{const value=JSON.parse(localStorage.getItem(customAccountsKey)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return {}}}
function syncCustomAccounts(){for(const [id,value] of Object.entries(customAccounts()))if(/^custom_[a-z0-9_]+$/.test(id)&&Array.isArray(value)&&typeof value[0]==='string'&&['asset','liability','equity','income','expense'].includes(value[1]))accounts[id]=value}
syncCustomAccounts();
export function statements(entries,currency,from,to){
 const end=to||'9999-12-31', start=from||'0000-01-01'; const balances=Object.fromEntries(Object.keys(accounts).map(k=>[k,0]));const period={revenue:0,expense:0,grossRevenue:0,revenueReductions:0,expenseCategories:{}};
 for(const e of entries){if(e.currency!==currency||e.date>end||!accounts[e.debit]||!accounts[e.credit]||!Number.isSafeInteger(e.amount)||e.amount<=0)continue; balances[e.debit]+=e.amount;balances[e.credit]-=e.amount;if(e.date>=start){if(accounts[e.credit][1]==='income'){period.revenue+=e.amount;period.grossRevenue+=e.amount}if(accounts[e.debit][1]==='income'){period.revenue-=e.amount;period.revenueReductions+=e.amount}if(accounts[e.debit][1]==='expense'){period.expense+=e.amount;period.expenseCategories[e.debit]=(period.expenseCategories[e.debit]||0)+e.amount}if(accounts[e.credit][1]==='expense'){period.expense-=e.amount;period.expenseCategories[e.credit]=(period.expenseCategories[e.credit]||0)-e.amount}}}
 const sumType=type=>Object.keys(accounts).filter(k=>accounts[k][1]===type).reduce((n,k)=>n+balances[k],0);const assets=sumType('asset'),liabilities=-sumType('liability'),equity=-sumType('equity')-sumType('income')-sumType('expense');
 return {balances,period,assets,liabilities,equity,net:period.revenue-period.expense};
}
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,c)=>new Intl.NumberFormat('en-US',{style:'currency',currency:c}).format(n/100);
const key='crm-demo-journal-v1';
function store(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{alert('Not saved: browser storage is full or unavailable.');return false}}
function read(){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch{return []}}
export function sourceTransactions(state,currency,from='',to=''){
 const matters=new Map((state.matters||[]).map(m=>[m.id,m]));
 const within=x=>x.status==='Approved'&&matters.get(x.matterId)?.currency===currency&&(!from||x.date>=from)&&(!to||x.date<=to);
 return [...(state.payments||[]).filter(within).map(p=>({...p,kind:'Payment'})),...(state.refunds||[]).filter(within).map(r=>({...r,kind:'Refund'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)));
}
const classKey='crm-demo-classifications-v1';
function readClasses(){try{return JSON.parse(localStorage.getItem(classKey)||'{}')||{}}catch{return {}}}
const signature=(p,currency)=>JSON.stringify([p.id,p.matterId,p.amount,p.date,currency,p.status]);
export function derivedEntries(state,currency,classes){
 const source=sourceTransactions(state,currency), payments=new Map(source.filter(x=>x.kind==='Payment').map(x=>[x.id,x]));
 const refunds=[],refunded=new Map();for(const x of source.filter(x=>x.kind==='Refund').sort((a,b)=>a.date.localeCompare(b.date)||String(a.id).localeCompare(String(b.id)))){const p=payments.get(x.paymentId),used=refunded.get(x.paymentId)||0;if(!p||x.matterId!==p.matterId||x.date<p.date||!Number.isSafeInteger(x.amount)||x.amount<=0||used+x.amount>p.amount)continue;refunded.set(x.paymentId,used+x.amount);refunds.push(x);}
 const out=[];
 for(const p of payments.values()){const cl=classes[p.id];if(!cl||cl.signature!==signature(p,currency)||!['earned','advance'].includes(cl.kind))continue;out.push({currency,date:p.date,amount:p.amount,debit:'cash',credit:cl.kind==='earned'?'revenue':'clientfunds',memo:'Approved payment '+p.id});}
 for(const p of payments.values()){
  const cl=classes[p.id];if(!cl||cl.signature!==signature(p,currency)||!['earned','advance'].includes(cl.kind))continue;
  let unearned=cl.kind==='advance'?p.amount:0,earned=cl.kind==='earned'?p.amount:0;
  const recognition=cl.kind==='advance'?(Array.isArray(cl.recognitions)?cl.recognitions:[]):[];
  const events=[...refunds.filter(x=>x.paymentId===p.id).map(x=>({...x,event:'refund'})),...recognition.map((x,i)=>({...x,id:String(i),event:'recognition'}))].sort((a,b)=>String(a.date).localeCompare(String(b.date))||(a.event===b.event?String(a.id).localeCompare(String(b.id)):(a.event==='refund'?-1:1)));
  for(const x of events){if(x.date<p.date||!Number.isSafeInteger(x.amount)||x.amount<=0)continue;
   if(x.event==='recognition'){if(x.amount>unearned)continue;unearned-=x.amount;earned+=x.amount;out.push({currency,date:x.date,amount:x.amount,debit:'clientfunds',credit:'revenue',memo:'Advance earned '+p.id});}
   else {let liability=Math.min(unearned,x.amount),revenue=x.amount-liability;if(revenue>earned)continue;if(liability)out.push({currency,date:x.date,amount:liability,debit:'clientfunds',credit:'cash',memo:'Approved refund '+x.id});if(revenue)out.push({currency,date:x.date,amount:revenue,debit:'revenue',credit:'cash',memo:'Approved refund '+x.id});unearned-=liability;earned-=revenue;}
  }
 }

 return out;
}
export function showAccounting(host,state,view=null){
 const box=document.createElement('section'); box.className='card card-body';box.style.marginTop='18px';host.append(box);
 let currency='BDT',from='',to='',ledgerAccount='cash';
 function draw(){const all=read(),classes=readClasses(),auto=derivedEntries(state,currency,classes),r=statements([...all,...auto],currency,from,to);const source=sourceTransactions(state,currency,from,to);const sourceRows=source.map(x=>`<tr><td>${safe(x.date)}</td><td>${x.kind}</td><td>${safe(state.matters.find(m=>m.id===x.matterId)?.ref||'—')}</td><td>${money(x.amount,currency)}</td><td>${x.kind==='Payment'?`<select class="payment-class" data-id="${safe(x.id)}" aria-label="Classification"><option value="">Needs classification</option><option value="earned" ${classes[x.id]?.signature===signature(x,currency)&&classes[x.id]?.kind==='earned'?'selected':''}>Earned service fee</option><option value="advance" ${classes[x.id]?.signature===signature(x,currency)&&classes[x.id]?.kind==='advance'?'selected':''}>Unearned advance</option></select>${classes[x.id]?.signature===signature(x,currency)&&classes[x.id]?.kind==='advance'?`<div><label>Earned date <input type="date" class="earned-date" data-id="${safe(x.id)}" min="${safe(x.date)}"></label> <label>Amount <input type="number" class="earned-amount" data-id="${safe(x.id)}" min="0.01" step="0.01"></label> <button type="button" class="add-earned" data-id="${safe(x.id)}">Add earned amount</button><small>Enter each completed portion separately.</small>${(classes[x.id].recognitions||[]).map(z=>`<div>${safe(z.date)}: ${money(z.amount,currency)}</div>`).join('')}</div>`:''}`:(auto.some(e=>e.memo==='Approved refund '+x.id)?'Follows original payment':'Review original payment')}</td></tr>`).join('');const options=Object.entries(accounts).map(([id,[name,type]])=>`<option value="${id}">${safe(name)} (${type})</option>`).join('');const rows=all.filter(x=>x.currency===currency&&(!from||x.date>=from)&&(!to||x.date<=to)).map(x=>`<tr><td>${safe(x.date)}</td><td>${safe(x.memo)}</td><td>${safe(accounts[x.debit]?.[0])}</td><td>${safe(accounts[x.credit]?.[0])}</td><td>${money(x.amount,currency)}</td></tr>`).join('');
 const ledgerEntries=[...all,...auto].filter(e=>e.currency===currency&&(!to||e.date<=to)&&(e.debit===ledgerAccount||e.credit===ledgerAccount)).sort((a,b)=>String(a.date).localeCompare(String(b.date)));let ledgerBalance=0;for(const e of ledgerEntries.filter(e=>from&&e.date<from))ledgerBalance+=(e.debit===ledgerAccount?e.amount:0)-(e.credit===ledgerAccount?e.amount:0);const opening=ledgerBalance;const ledgerRows=ledgerEntries.filter(e=>!from||e.date>=from).map(e=>{const debit=e.debit===ledgerAccount?e.amount:0,credit=e.credit===ledgerAccount?e.amount:0;ledgerBalance+=debit-credit;return `<tr><td>${safe(e.date)}</td><td>${safe(e.memo)}</td><td>${debit?money(debit,currency):'—'}</td><td>${credit?money(credit,currency):'—'}</td><td>${money(ledgerBalance,currency)}</td></tr>`}).join('');
 const accountRows=type=>Object.entries(accounts).filter(([id,v])=>v[1]===type&&r.balances[id]!==0).map(([id,v])=>`<tr><td>${safe(v[0])}</td><td class="account-amount">${money((type==='asset'?1:-1)*r.balances[id],currency)}</td></tr>`).join('');
 const expenseRows=Object.entries(r.period.expenseCategories).map(([id,amount])=>`<tr><td>${safe(accounts[id][0])}</td><td class="account-amount">${money(amount,currency)}</td></tr>`).join('');
 box.innerHTML=`<h2>Accounting reports — demo ledger</h2><p>Demo only. Classified approved payments and linked refunds are calculated automatically; unclassified items are excluded. Use fictional data only.</p><div class="form-grid"><div class="field"><label>Currency</label><select id="ledger-currency"><option ${currency==='BDT'?'selected':''}>BDT</option><option ${currency==='USD'?'selected':''}>USD</option></select></div><div class="field"><label>From</label><input id="ledger-from" type="date" value="${safe(from)}"></div><div class="field"><label>To / balance sheet date</label><input id="ledger-to" type="date" value="${safe(to)}"></div></div><h3>Approved payments and refunds</h3><p>Select the correct classification for each payment. Refunds reduce the remaining unearned amount first, then earned revenue. On the same date refunds are applied before earned amounts. Enter each earned portion with its date. Review any refund exceeding the payment. Unclassified or changed payments are excluded until reviewed. Manual journal entries are separate: avoid entering the same transaction twice.</p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Case</th><th>Amount</th><th>Accounting status</th></tr></thead><tbody>${sourceRows||'<tr><td colspan="5">No approved transactions for this period.</td></tr>'}</tbody></table></div><h3>Add balanced journal entry</h3><div class="form-grid"><div class="field"><label for="new-account-name">New account name</label><input id="new-account-name" maxlength="60" placeholder="e.g. Travel expense"></div><div class="field"><label for="new-account-type">Account type</label><select id="new-account-type"><option value="expense">Expense</option><option value="income">Income</option><option value="asset">Asset</option><option value="liability">Liability</option><option value="equity">Equity</option></select></div><div class="field"><label>Manage accounts</label><button type="button" class="btn small" id="add-account">+ Add account</button></div><div class="field"><label for="remove-account">Remove a custom account</label><select id="remove-account"><option value="">Select account</option>${Object.entries(customAccounts()).filter(([id])=>accounts[id]).map(([id,v])=>`<option value="${safe(id)}">${safe(v[0])} (${safe(v[1])})</option>`).join('')}</select><button type="button" class="btn small" id="delete-account">Delete account</button></div></div><p>Accounts already used in a journal entry cannot be deleted.</p><form id="journal-form"><div class="form-grid"><div class="field"><label>Date</label><input name="date" type="date" required></div><div class="field"><label>Description</label><input name="memo" required maxlength="100"></div><div class="field"><label>Debit</label><select name="debit">${options}</select></div><div class="field"><label>Credit</label><select name="credit">${options}</select></div><div class="field"><label>Amount (${currency})</label><input name="amount" type="number" min="0.01" step="0.01" required></div></div><button class="btn small" type="submit">Add journal entry</button></form><section class="print-report" data-report="income"><h3>Income Statement (${currency})</h3><button type="button" class="btn small print-report-button" data-print="income">Print Income Statement</button><p>Period: ${safe(from||'All dates')} to ${safe(to||'All dates')}</p><table class="financial-report"><tbody><tr><th colspan="2">Income</th></tr><tr><td>Service and other earned income</td><td class="account-amount">${money(r.period.grossRevenue,currency)}</td></tr><tr><td>Less: refunds and other income reductions</td><td class="account-amount">(${money(r.period.revenueReductions,currency)})</td></tr><tr class="report-total"><th>Net income</th><th class="account-amount">${money(r.period.revenue,currency)}</th></tr><tr><th colspan="2">Operating expenses</th></tr>${expenseRows||'<tr><td colspan="2">No expenses for this period.</td></tr>'}<tr class="report-total"><th>Total expenses</th><th class="account-amount">${money(r.period.expense,currency)}</th></tr><tr class="report-total"><th>Net profit / loss</th><th class="account-amount">${money(r.net,currency)}</th></tr></tbody></table></section><section class="print-report" data-report="balance"><h3>Balance Sheet (${currency})</h3><button type="button" class="btn small print-report-button" data-print="balance">Print Balance Sheet</button><p>As of: ${safe(to||'All dates')}</p><table class="financial-report"><tbody><tr><th colspan="2">Assets</th></tr>${accountRows('asset')}<tr class="report-total"><th>Total assets</th><th class="account-amount">${money(r.assets,currency)}</th></tr><tr><th colspan="2">Liabilities</th></tr>${accountRows('liability')}<tr class="report-total"><th>Total liabilities</th><th class="account-amount">${money(r.liabilities,currency)}</th></tr><tr><th colspan="2">Equity</th></tr>${accountRows('equity')}<tr><td>Accumulated profit / loss</td><td class="account-amount">${money(r.equity+Object.keys(accounts).filter(k=>accounts[k][1]==='equity').reduce((n,k)=>n+r.balances[k],0),currency)}</td></tr><tr class="report-total"><th>Total equity</th><th class="account-amount">${money(r.equity,currency)}</th></tr><tr class="report-total"><th>Total liabilities and equity</th><th class="account-amount">${money(r.liabilities+r.equity,currency)}</th></tr></tbody></table><p>Balance sheet includes all entries through the To date; income statement uses the selected period. Opening balances must be entered.</p></section><section class="print-report" data-report="journal"><h3>Journal (manual entries)</h3><button type="button" class="btn small print-report-button" data-print="journal">Print Journal</button><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Debit</th><th>Credit</th><th>Amount</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No journal entries for this period.</td></tr>'}</tbody></table></div></section><section class="print-report" data-report="ledger"><h3>General Ledger</h3><div class="field"><label for="ledger-account">Account</label><select id="ledger-account">${Object.entries(accounts).map(([id,v])=>`<option value="${safe(id)}" ${ledgerAccount===id?'selected':''}>${safe(v[0])}</option>`).join('')}</select></div><button type="button" class="btn small print-report-button" data-print="ledger">Print Ledger</button><p>Account: ${safe(accounts[ledgerAccount]?.[0])} · Opening balance (debit minus credit): ${money(opening,currency)}</p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Debit</th><th>Credit</th><th>Balance (debit − credit)</th></tr></thead><tbody>${ledgerRows||'<tr><td colspan="5">No activity for this period.</td></tr>'}</tbody></table></div></section>`;
 if(view){const children=Array.from(box.children),filters=box.querySelector('.form-grid'),selected=box.querySelector(`[data-report="${view}"]`);children.forEach(el=>{if(el!==filters&&el!==selected)el.hidden=true});}
 box.querySelector('#ledger-account').onchange=e=>{ledgerAccount=e.target.value;draw()};
 box.querySelector('#add-account').onclick=()=>{const name=box.querySelector('#new-account-name').value.trim(),type=box.querySelector('#new-account-type').value;if(!name){alert('Enter an account name.');return}if(Object.values(accounts).some(v=>v[0].toLowerCase()===name.toLowerCase())){alert('This account name already exists.');return}const id='custom_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8),data=customAccounts();data[id]=[name,type];try{localStorage.setItem(customAccountsKey,JSON.stringify(data))}catch{alert('Unable to save the account in this browser.');return}accounts[id]=data[id];draw()};
 box.querySelector('#delete-account').onclick=()=>{const id=box.querySelector('#remove-account').value,data=customAccounts();if(!id||!data[id]){alert('Select a custom account to remove.');return}if(read().some(e=>e.debit===id||e.credit===id)){alert('This account is used in a journal entry and cannot be deleted.');return}delete data[id];try{localStorage.setItem(customAccountsKey,JSON.stringify(data))}catch{alert('Unable to update accounts in this browser.');return}delete accounts[id];if(ledgerAccount===id)ledgerAccount='cash';draw()};
 box.querySelectorAll('.print-report-button').forEach(button=>{button.onclick=()=>{const section=box.querySelector(`[data-report="${button.dataset.print}"]`),frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);const doc=frame.contentDocument,period=button.dataset.print==='balance'?`As of: ${to||'All dates'}`:`From: ${from||'All dates'} · To: ${to||'All dates'}`;doc.open();doc.write(`<!doctype html><html><head><title>Accounting report</title><style>body{font:14px Arial,sans-serif;color:#111;padding:24px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #888;padding:8px;text-align:left}button{display:none}h3{font-size:20px}.account-amount{text-align:right}.report-total th{border-top:2px solid #333}</style></head><body><p>Demo accounting report · ${safe(currency)} · ${safe(period)}</p>${section.outerHTML}</body></html>`);doc.close();frame.contentWindow.onafterprint=()=>frame.remove();frame.contentWindow.focus();frame.contentWindow.print()}});
 box.querySelectorAll('.payment-class').forEach(el=>{el.onchange=()=>{const p=source.find(x=>x.kind==='Payment'&&x.id===el.dataset.id);if(!p)return;const data=readClasses();if(el.value)data[p.id]={kind:el.value,signature:signature(p,currency)};else delete data[p.id];store(classKey,data);draw()}});box.querySelectorAll('.add-earned').forEach(el=>{el.onclick=()=>{const p=source.find(x=>x.kind==='Payment'&&x.id===el.dataset.id),data=readClasses(),cl=p&&data[p.id];if(!p||!cl||cl.kind!=='advance'||cl.signature!==signature(p,currency))return;const date=box.querySelectorAll('.earned-date'),amount=box.querySelectorAll('.earned-amount');const d=Array.from(date).find(x=>x.dataset.id===p.id)?.value,n=Math.round(Number(Array.from(amount).find(x=>x.dataset.id===p.id)?.value)*100);if(!d||d<p.date||!Number.isSafeInteger(n)||n<=0){alert('Enter a valid date and amount.');return}const next={...cl,recognitions:[...(cl.recognitions||[]),{date:d,amount:n}]},test={...data,[p.id]:next},allEvents=derivedEntries(state,currency,test),earned=allEvents.filter(x=>x.memo==='Advance earned '+p.id).length;if(earned!==next.recognitions.length){alert('Amount exceeds the available advance on that date, or conflicts with another entry.');return}data[p.id]=next;store(classKey,data);draw()}});box.querySelector('#ledger-currency').onchange=e=>{currency=e.target.value;draw()};box.querySelector('#ledger-from').onchange=e=>{from=e.target.value;draw()};box.querySelector('#ledger-to').onchange=e=>{to=e.target.value;draw()};box.querySelector('#journal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=f.get('debit'),c=f.get('credit'),amount=Math.round(Number(f.get('amount'))*100);if(d===c||!Number.isSafeInteger(amount)||amount<=0){alert('Choose different accounts and a valid amount.');return}if(!/^\d{4}-\d{2}-\d{2}$/.test(String(f.get('date')||''))||!String(f.get('memo')||'').trim()){alert('Enter a valid date and description.');return}all.push({date:f.get('date'),memo:String(f.get('memo')).trim(),debit:d,credit:c,amount,currency});if(!store(key,all))all.pop();draw()};
 }draw();
}
